@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final KafkaTemplate<String, OrderEvent> kafkaTemplate;
    private final OrderGrpcClient grpcClient;

    public OrderController(KafkaTemplate<String, OrderEvent> kafkaTemplate, OrderGrpcClient grpcClient) {
        this.kafkaTemplate = kafkaTemplate;
        this.grpcClient = grpcClient;
    }

    @PostMapping
    public ResponseEntity<String> createOrder(@RequestBody OrderRequest request) {
        // Synchronous call to validate inventory via gRPC for ultra-low latency
        InventoryResponse inventory = grpcClient.checkInventory(request.getProductId(), request.getQuantity());
        if (!inventory.getInStock()) {
            return ResponseEntity.badRequest().body("Out of stock");
        }

        // Asynchronous emission of order created event for downstream fulfillment
        OrderEvent event = new OrderEvent(request.getOrderId(), request.getProductId());
        kafkaTemplate.send("order-events", event.getOrderId(), event);

        return ResponseEntity.accepted().body("Order processing initiated");
    }
}
